// Writes the picture of the benchmark task scene-rendering-11 (decision 0089): a 4 x 4 RGBA PNG whose 16 texels are
// all different, so that a flip, a mirror or a transposition of the picture changes every texel. The same bytes are
// the task asset of both sides, in the Mtek starter and reference and in the three.js starter and reference
// (`assets/swatch.png` in each project); `--check` fails when a copy differs or the generated bytes changed.
//
//   node evidence/M6/benchmark-texture/make-swatch.mjs           write the four copies
//   node evidence/M6/benchmark-texture/make-swatch.mjs --check   verify them
//
// The bytes are deterministic (no timestamps, fixed zlib level), a plain 8-bit RGBA PNG without colour-space chunks.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { deflateSync } from "node:zlib";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const task = join(root, "benchmarks", "tasks", "scene-rendering-11");
export const COPIES = ["mtek", "baseline", "reference/mtek", "reference/baseline"].map((dir) =>
  join(task, ...dir.split("/"), "assets", "swatch.png"),
);

/** The texels, row by row, top row first, as sRGB bytes. */
export const TEXELS = [
  ["#bc4020", "#e0a010", "#20a060", "#6060dc"],
  ["#d02890", "#40c8c8", "#a0a0a0", "#101050"],
  ["#f0e060", "#804010", "#30d030", "#c060f0"],
  ["#606060", "#e03030", "#2080e0", "#f8f8f8"],
];

export const bytesOf = (hex) => [1, 3, 5].map((i) => Number.parseInt(hex.slice(i, i + 2), 16));

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();
function crc32(buffer) {
  let c = 0xffffffff;
  for (const byte of buffer) c = CRC_TABLE[(c ^ byte) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const head = Buffer.alloc(8);
  head.writeUInt32BE(data.length, 0);
  head.write(type, 4, "ascii");
  const tail = Buffer.alloc(4);
  tail.writeUInt32BE(crc32(Buffer.concat([head.subarray(4), data])), 0);
  return Buffer.concat([head, data, tail]);
}

export function swatchPng() {
  const height = TEXELS.length;
  const width = TEXELS[0].length;
  const rows = TEXELS.map((row) => Buffer.from([0, ...row.flatMap((hex) => [...bytesOf(hex), 255])]));
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header[8] = 8; // bit depth
  header[9] = 6; // RGBA
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", header),
    chunk("IDAT", deflateSync(Buffer.concat(rows), { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

function main(argv) {
  const png = swatchPng();
  if (argv.includes("--check")) {
    let bad = 0;
    for (const file of COPIES) {
      let actual = null;
      try {
        actual = readFileSync(file);
      } catch {
        // missing
      }
      if (actual === null || !actual.equals(png)) {
        process.stderr.write(`differs or missing: ${file.slice(root.length + 1)}\n`);
        bad += 1;
      }
    }
    if (bad > 0) return 1;
    process.stdout.write(`swatch.png: ${String(COPIES.length)} copies identical to the generated ${String(png.length)} bytes\n`);
    return 0;
  }
  for (const file of COPIES) {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, png);
  }
  process.stdout.write(`wrote ${String(COPIES.length)} copies of ${String(png.length)} bytes\n`);
  return 0;
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));
